-- BEGIN BUNDLED LIBRARIES (tools/bundle_libs.py)
-- Generated by tools/bundle_libs.py — do not edit by hand. Regenerate with: python3 tools/bundle_libs.py
local __LIBS = {}
local __LOADERS = {}
-- Forward declaration: libraries call require_lib at load time.
local require_lib

__LOADERS["catalog"] = function(...)
-- =====================================================================
-- Lib: catalog/pagination helpers for plugin catalogs: hasNextPage,
--      nextIndex/pageUrl (dominant "?page=N" scheme), urlEncode.
-- Loaded via require_lib("catalog"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

-- =====================================================================
-- Pagination
-- =====================================================================

-- "Has next page" for the dominant scheme where a page is considered
-- non-final as long as it returned any item (39 inline copies of
-- `#items > 0`, plus 7 local hasNextPage helpers with the same body).
-- Plugins that know their total page count keep their own comparison.
function M.hasNextPage(items)
    return type(items) == "table" and #items > 0
end

-- Catalog index is 0-based; pages on the wire are 1-based — the
-- dominant `local page = index + 1` from 74 plugins.
function M.nextIndex(index)
    return (index or 0) + 1
end

-- Build a page URL from a template with "{n}" where the 1-based page
-- number goes. Matches the dominant string-concat schemes:
--   ".../catalog?page={n}"        (guide, most sites)
--   "...&pg={n}"                  (en/scribblehub.lua:33)
--   "...&bpage={n}"               (ru/bookhamster.lua:85)
-- Sites with conditional page params or API cursors keep their own code.
function M.pageUrl(template, index)
    return (template:gsub("{n}", tostring(M.nextIndex(index))))
end

-- =====================================================================
-- Query encoding
-- =====================================================================

-- Pure-Lua mirror of the engine global url_encode (Java
-- URLEncoder.encode(s, "UTF-8"): application/x-www-form-urlencoded —
-- space -> "+", unreserved A-Za-z0-9 . - * _ kept, everything else
-- "%XX" uppercase over UTF-8 bytes, "\n" normalized to "\r\n" first).
-- The 73 plugin call sites use the engine global directly; this copy
-- exists for shared libs and parity tests outside the engine.
-- Byte-wise whitelist: LuaJ's %w matches Latin-1 letters (0xC0-0xFF), so a
-- UTF-8 byte like 0xE3 would stay raw and corrupt the query (CJK/Cyrillic
-- search returned 0). Java URLEncoder keeps only A-Z a-z 0-9 . - * _.
local function unreserved(b)
    return (b >= 48 and b <= 57)
        or (b >= 65 and b <= 90)
        or (b >= 97 and b <= 122)
        or b == 45 or b == 46 or b == 42 or b == 95
end

function M.urlEncode(s)
    if type(s) ~= "string" then return s end
    s = s:gsub("\n", "\r\n")
    return (s:gsub(".", function(c)
        local b = string.byte(c)
        if b == 32 then return "+" end
        if unreserved(b) then return c end
        return string.format("%%%02X", b)
    end))
end

return M
end

__LOADERS["urls"] = function(...)
-- =====================================================================
-- Lib: shared URL helpers (origin, unescapeSlashes, hostOf, resolve,
--      absUrl, driveDirectUrl) for videohost and novel extractors.
-- Loaded via require_lib("urls"). No dependencies on other libs.
-- =====================================================================
local version = "1.2.0"

local M = {}

-- =====================================================================
-- URL helpers
-- =====================================================================

function M.origin(url)
    local scheme, host = url:match("^(https?)://([^/?#]+)")
    if not scheme then return nil end
    return scheme .. "://" .. host .. "/"
end

function M.unescapeSlashes(s)
    local r = s:gsub("\\/", "/")
    r = r:gsub("\\u0026", "&")
    return r
end

function M.hostOf(url)
    return ((url or ""):match("^https?://([^/?#:]+)") or ""):lower()
end

-- Relative / protocol-relative URL -> absolute (relative to the embed).
function M.resolve(u, embedUrl)
    u = M.unescapeSlashes(u)
    if u:sub(1, 2) == "//" then return "https:" .. u end
    if u:find("^https?://") then return u end
    local o = M.origin(embedUrl or "")
    if o then
        o = o:gsub("/$", "")
        return o .. (u:sub(1, 1) == "/" and u or ("/" .. u))
    end
    return u
end

-- RFC 3986 merge, mirroring java.net.URI(base):resolve(href) — the exact
-- semantics of the engine global url_resolve (plugin-tester-jvm
-- LuaEngineCli.kt:355). Used only when that global is unavailable
-- (offline tests); in the app the global always wins.
local function removeDotSegments(p)
    local leading = p:sub(1, 1) == "/"
    local segs = {}
    for seg in p:gmatch("[^/]+") do
        if seg == ".." then
            if #segs > 0 and segs[#segs] ~= ".." then
                segs[#segs] = nil
            elseif not leading then
                segs[#segs + 1] = seg
            end
        elseif seg ~= "." then
            segs[#segs + 1] = seg
        end
    end
    local out = table.concat(segs, "/")
    if leading then out = "/" .. out end
    if p:sub(-1) == "/" and out:sub(-1) ~= "/" then out = out .. "/" end
    return out
end

local function splitRef(u)
    local path, query, fragment = u, "", ""
    local hash = path:find("#", 1, true)
    if hash then fragment = path:sub(hash + 1) path = path:sub(1, hash - 1) end
    local qm = path:find("?", 1, true)
    if qm then query = path:sub(qm + 1) path = path:sub(1, qm - 1) end
    return path, query, fragment
end

local function resolveRef(base, ref)
    if type(base) ~= "string" or type(ref) ~= "string" then return ref end
    if ref:match("^%a[%w+.-]*:") then return ref end
    local scheme, authority, rest = base:match("^(%a[%w+.-]*)://([^/?#]*)(.*)$")
    if not scheme then return ref end
    if ref:sub(1, 2) == "//" then return scheme .. "://" .. ref:sub(3) end
    local rPath, rQuery, rFrag = splitRef(ref)
    local bPath, bQuery = splitRef(rest)
    local path, query
    if rPath == "" then
        path = bPath
        query = (rQuery ~= "") and rQuery or bQuery
    elseif rPath:sub(1, 1) == "/" then
        path = rPath
        query = rQuery
    else
        path = (bPath:match("^.*/") or "/") .. rPath
        query = rQuery
    end
    local out = scheme .. "://" .. authority .. removeDotSegments(path)
    if query ~= "" then out = out .. "?" .. query end
    if rFrag ~= "" then out = out .. "#" .. rFrag end
    return out
end

-- href found in a page -> absolute URL, relative to `base` (usually baseUrl).
-- Union of the two inline variants: the dominant url_resolve one (guide:1763,
-- 36 byte-identical copies, e.g. ru/ranobehub.lua:11) and the manual sub/find
-- one (es/latanime.lua:94, en/hianimes.lua:50, id/anichin.lua:70). They agree
-- on absolute / protocol-relative / root-relative hrefs; for a bare relative
-- href the canonical url_resolve merge (RFC 3986) is used, the manual copies
-- joined it as baseDir .. "/" .. href — plugins relying on that join must be
-- checked during migration. Empty or non-string href -> "" (guide template).
function M.absUrl(base, href)
    if type(href) ~= "string" or href == "" then return "" end
    if href:sub(1, 4) == "http" then return href end
    if href:sub(1, 2) == "//" then return "https:" .. href end
    if type(url_resolve) == "function" then return url_resolve(base, href) end
    return resolveRef(base, href)
end

-- Google Drive file page -> direct usercontent download URL, no network:
-- the file id lives in the link itself (checked live 2026-10-03, usercontent
-- with confirm=t answers 206 without a single header).
-- Merged from the four inline copies: ar/anime4up.lua:813, ar/witanime.lua:1423,
-- ar/animephoenix.lua:698, es/latanime.lua:280 — all equivalent; the union keeps
-- the nil-safe host match (anime4up dereferenced match() without `or ""`).
-- ponytail: no playback-API fallback for "download disabled" (403 + UA binding) —
-- add it when locked links actually show up on the sites.
function M.driveDirectUrl(link)
    if type(link) ~= "string" then return nil end
    local host = (link:match("^https?://([^/]+)") or ""):lower()
    host = host:gsub("^www%.", "")
    if host ~= "drive.google.com" and host ~= "drive.usercontent.google.com" then
        return nil
    end
    local id = link:match("/file/d/([%w_-]+)") or link:match("[?&]id=([%w_-]+)")
    if not id then return nil end
    local u = "https://drive.usercontent.google.com/download?id=" .. id
        .. "&export=download&confirm=t"
    local rk = link:match("[?&]resourcekey=([%w_-]+)")
    if rk then u = u .. "&resourcekey=" .. rk end
    return u
end

return M
end

require_lib = function(id)
    local cached = rawget(__LIBS, id)
    if cached ~= nil then return cached end
    local loader = rawget(__LOADERS, id)
    if loader == nil then error("bundle_libs: unknown library id: " .. tostring(id), 2) end
    local value = loader()
    __LIBS[id] = value
    return value
end
-- END BUNDLED LIBRARIES (tools/bundle_libs.py)
-- ── Метаданные ──
id       = "fictionzone"
name     = "Fiction Zone"
version  = "1.1.1"
baseUrl  = "https://fictionzone.net/"
language = {"en", "es", "fr"}
icon     = "https://raw.githubusercontent.com/Stlucifer15t/external-sources/refs/heads/main/icons/fictionzone.png"

-- ── Хелперы ──

-- Все данные сайта отдаются через JSON API, спрятанный за POST-прокси
-- /api/__api_party/fictionzone (HTML-страницы закрыты Cloudflare, а прямые
-- GET к /platform/* отдают 404). Поэтому плагин ходит ТОЛЬКО через этот прокси.
local PROXY = baseUrl .. "api/__api_party/fictionzone"

-- Кэш деталей книги: 4 функции деталей вызываются движком параллельно с одним
-- bookUrl, а все вызовы одного плагина сериализованы через Mutex — кэш безопасен.
local _detailsCache = {}

-- Old builds ship no require_lib: keep the plugin loadable (a top-level error
-- would drop it from the source list) and fail with a visible message on the
-- first call instead. Shared libs load lazily and are cached per session.
local _libs
local function LIB(id)
  if type(require_lib) ~= "function" then
    show_error("Requires Dreamora update", "This plugin needs the shared libraries")
    error("Requires Dreamora update (require_lib)", 0)
  end
  if not _libs then _libs = {} end
  if not _libs[id] then _libs[id] = require_lib(id) end
  return _libs[id]
end

-- absUrl: относительные ссылки -> абсолютные (shared urls lib)
local function absUrl(href)
  return LIB("urls").absUrl(baseUrl, href)
end

-- Engine global url_encode delegates to the shared catalog lib.
local url_encode = function(s) return LIB("catalog").urlEncode(s) end

-- Универсальный GET к API через прокси. Возвращает payload (.data) или nil.
-- Полный текст главы сайт отдаёт только авторизованному пользователю: анонимный
-- запрос возвращает урезанное превью (~половину). Прокси прокидывает заголовок
-- authorization из тела на upstream, поэтому подставляем Bearer-токен из кук
-- пользователя (fz_access_token), когда он залогинен в Dreamora. Без токена
-- работаем анонимно (превью) — обратно-совместимо.
local function apiGet(path)
  local ts = os.date("!%Y-%m-%dT%H:%M:%SZ")
  local headers = {
    { "content-type", "application/json" },
    { "x-request-time", ts },
  }
  local cookies = get_cookies(baseUrl)
  local token = cookies and cookies["fz_access_token"] or ""
  if token ~= "" then
    headers[#headers + 1] = { "authorization", "Bearer " .. token }
  end
  local body = json_stringify({
    path = path,
    headers = headers,
    method = "GET",
  })
  local r = http_post(PROXY, body, {
    headers = {
      ["Content-Type"] = "application/json",
      ["Accept"] = "application/json",
    },
  })
  if not r.success then
    log_error("fictionzone: API request failed: " .. path)
    return nil
  end
  local parsed = json_parse(r.body)
  if not parsed or not parsed.data then return nil end
  return parsed.data
end

-- Детали книги по bookUrl (novel/<slug>). Результат кэшируется по slug.
local function getDetails(bookUrl)
  local slug = bookUrl:match("novel/(.+)")
  if not slug then return nil end
  slug = slug:gsub("/.*", "") -- убираем всё после слэша (query/ trailing), если движок что-то добавил
  if _detailsCache[slug] then return _detailsCache[slug] end
  local data = apiGet("/platform/novel-details?slug=" .. slug)
  if data then _detailsCache[slug] = data end
  return data
end

-- Обложка Fiction Zone лежит на img.fictionzone.net, который не резолвится.
-- Рабочий вариант — CDN imageproxy: cdn.fictionzone.net/insecure/rs:fill:300:400/<base64>.webp
-- (увеличенное разрешение для чёткости в каталоге/поиске/деталях)
local function coverUrl(imageB64)
  if not imageB64 or imageB64 == "" then return nil end
  return "https://cdn.fictionzone.net/insecure/rs:fill:300:400/" .. imageB64 .. ".webp"
end

-- ── Каталог ──

function getCatalogList(index)
  local page = LIB("catalog").nextIndex(index)
  local data = apiGet("/platform/browse?page=" .. page
    .. "&page_size=20&sort_by=bookmark_count&sort_order=desc&include_genres=true")
  if not data then return { items = {}, hasNext = false } end

  local items = {}
  for _, n in ipairs(data.novels) do
    items[#items + 1] = {
      title  = n.title,
      url    = absUrl("novel/" .. n.slug),
      cover  = coverUrl(n.image),
      rating = n.rating,
    }
  end
  return { items = items, hasNext = data.pagination.has_next }
end

function getCatalogSearch(index, query)
  local page = LIB("catalog").nextIndex(index)
  local data = apiGet("/platform/browse?search=" .. url_encode(query)
    .. "&page=" .. page
    .. "&page_size=20&search_in_synopsis=true&sort_by=bookmark_count&sort_order=desc&include_genres=true")
  if not data then return { items = {}, hasNext = false } end

  local items = {}
  for _, n in ipairs(data.novels) do
    items[#items + 1] = {
      title  = n.title,
      url    = absUrl("novel/" .. n.slug),
      cover  = coverUrl(n.image),
      rating = n.rating,
    }
  end
  return { items = items, hasNext = data.pagination.has_next }
end

-- ── Фильтры ──

-- Серверная фильтрация: genre_ids (включение жанров), tag_ids (включение тегов),
-- exclude_tag_ids (исключение тегов) и sort_by. status/type/origin_language API
-- игнорирует (фильтруются на клиенте сайта) — в плагине их нет.
-- Для checkbox движок передаёт значения в filters[key .. "_included"] (массив).
-- ВАЖНО: API принимает несколько значений ОДНИМ параметром через запятую
-- (tag_ids=1,2,3 — логическое ИЛИ), а не повтором параметра: повтор
-- (&tag_ids=1&tag_ids=2) учитывает только первое значение и ломает мульти-выбор.
local function joinIds(vals)
  if type(vals) == "table" then
    local t = {}
    for _, v in ipairs(vals) do t[#t + 1] = tostring(v) end
    return table.concat(t, ",")
  elseif type(vals) == "string" and vals ~= "" then
    return vals
  end
  return nil
end

function getFilterList()
  local filters = {
    {
      type       = "select",
      key        = "sort",
      label      = "Sort",
      defaultValue = "bookmark_count",
      options = {
        { value = "bookmark_count", label = "Most Bookmarked" },
        { value = "created_at",     label = "Latest" },
        { value = "rating",         label = "Top Rated" },
        { value = "chapter_count",  label = "Most Chapters" },
        { value = "review_count",   label = "Most Reviews" },
      },
    },
    {
      type        = "checkbox",
      key         = "genre",
      label       = "Genre",
      multiselect = true,
      options = {
        { value = "3", label = "Fan-Fiction" },
        { value = "1", label = "Fantasy" },
        { value = "8", label = "Romance" },
        { value = "6", label = "Sci-Fi" },
        { value = "2", label = "Urban" },
        { value = "7", label = "Virtual Reality" },
      },
    },
  }

  -- Теги (их ~90) берём динамически из API, чтобы не хардкодить список.
  local tagsData = apiGet("/platform/tags")
  if tagsData then
    local includeOpts = {}
    local excludeOpts = {}
    for _, t in ipairs(tagsData) do
      local opt = { value = tostring(t.id), label = t.name }
      includeOpts[#includeOpts + 1] = opt
      excludeOpts[#excludeOpts + 1] = opt
    end
    filters[#filters + 1] = {
      type        = "checkbox",
      key         = "tag",
      label       = "Tags (include)",
      multiselect = true,
      options     = includeOpts,
    }
    filters[#filters + 1] = {
      type        = "checkbox",
      key         = "tag_exclude",
      label       = "Tags (exclude)",
      multiselect = true,
      options     = excludeOpts,
    }
  end

  return filters
end

function getCatalogFiltered(index, filters)
  local page = LIB("catalog").nextIndex(index)
  local sort = filters["sort"] or "bookmark_count"
  local path = "/platform/browse?page=" .. page
    .. "&page_size=20&sort_by=" .. sort .. "&sort_order=desc&include_genres=true"

  local g = joinIds(filters["genre_included"] or filters["genre"])
  if g then path = path .. "&genre_ids=" .. g end

  local incl = joinIds(filters["tag_included"] or filters["tag"])
  if incl then path = path .. "&tag_ids=" .. incl end

  local excl = joinIds(filters["tag_exclude_included"] or filters["tag_exclude"])
  if excl then path = path .. "&exclude_tag_ids=" .. excl end

  local data = apiGet(path)
  if not data then return { items = {}, hasNext = false } end

  local items = {}
  for _, n in ipairs(data.novels) do
    items[#items + 1] = {
      title  = n.title,
      url    = absUrl("novel/" .. n.slug),
      cover  = coverUrl(n.image),
      rating = n.rating,
    }
  end
  return { items = items, hasNext = data.pagination.has_next }
end

-- ── Детали книги ──

function getBookTitle(bookUrl)
  local d = getDetails(bookUrl)
  if not d then return nil end
  return string_clean(d.title)
end

function getBookCoverImageUrl(bookUrl)
  local d = getDetails(bookUrl)
  if not d then return nil end
  return coverUrl(d.image)
end

function getBookDescription(bookUrl)
  local d = getDetails(bookUrl)
  if not d then return nil end
  return string_trim(d.synopsis)
end

function getBookGenres(bookUrl)
  local d = getDetails(bookUrl)
  if not d then return nil end
  local out = {}
  if d.genres then
    for _, g in ipairs(d.genres) do out[#out + 1] = g.name end
  end
  if d.tags then
    for _, t in ipairs(d.tags) do out[#out + 1] = t.name end
  end
  return out
end

function getBookRating(bookUrl)
  local d = getDetails(bookUrl)
  if not d or d.rating == nil then return nil end
  return tostring(d.rating)
end

function getBookStatus(bookUrl)
  local d = getDetails(bookUrl)
  if not d then return nil end
  local s = d.status
  if s == 1 then return "Ongoing" end
  if s == 0 then return "Completed" end
  return "Unknown"
end

function getBookLastUpdate(bookUrl)
  local d = getDetails(bookUrl)
  if not d or not d.chapter_last_created_at then return nil end
  local ts = d.chapter_last_created_at
  -- поле приходит либо строкой "YYYY-MM-DD HH:MM:SS", либо unix-временем (число)
  if type(ts) == "number" then
    return os.date("!%Y-%m-%d", ts)
  end
  return string.sub(tostring(ts), 1, 10)
end

-- ── Список глав ──

-- Контент главы отдаётся ТОЛЬКО через POST-прокси, а прямой GET по fictionzone.net
-- триггерит Cloudflare. Поэтому url главы указывает на реальную страницу книги
-- (движок её префетчит и вызывает getChapterText), а id книги и главы кодируем
-- в query (?c=<novel_id>.<chapter_id>), чтобы getChapterText сам догрузил текст.
function getChapterList(bookUrl)
  local slug = bookUrl:match("novel/(.+)")
  if slug then slug = slug:gsub("/.*", "") end
  local d = getDetails(bookUrl)
  if not d or not d.id then return {} end
  local nid = d.id
  local data = apiGet("/platform/chapter-lists?novel_id=" .. nid)
  if not data then return {} end

  local items = {}
  for _, c in ipairs(data.chapters) do
    items[#items + 1] = {
      title = c.title,
      url   = baseUrl .. "novel/" .. slug .. "?c=" .. nid .. "." .. c.chapter_id,
    }
  end
  return items
end

-- Быстрый детект новых глав: url последней главы. Без кэша (прямой запрос).
function getChapterListHash(bookUrl)
  local slug = bookUrl:match("novel/(.+)")
  if slug then slug = slug:gsub("/.*", "") end
  local d = getDetails(bookUrl)
  if not d or not d.id then return nil end
  local nid = d.id
  local data = apiGet("/platform/chapter-lists?novel_id=" .. nid)
  if not data or not data.chapters or #data.chapters == 0 then return nil end
  local last = data.chapters[#data.chapters]
  return baseUrl .. "novel/" .. slug .. "?c=" .. nid .. "." .. last.chapter_id
end

-- ── Текст главы ──

function getChapterText(html, url)
  local nid, cid = url:match("c=(%d+)%.(%d+)")
  if not nid or not cid then
    nid, cid = url:match("/r/(%d+)/(%d+)")
  end
  if not nid or not cid then
    log_error("fictionzone: cannot parse chapter url: " .. tostring(url))
    return ""
  end
  local data = apiGet("/platform/chapter-content?novel_id=" .. nid .. "&chapter_id=" .. cid)
  if not data or not data.content then return "" end

  -- content — чистый текст с переносами строк. Движок отображает результат
  -- getChapterText как ТЕКСТ, сохраняя переносы строк (как в syosetu/novelhi/
  -- novelight и др. — они возвращают html_text, а не оборачивают в <p>).
  -- Поэтому НЕ заворачиваем в <p>: иначе движок снимет теги, а вместе с ними
  -- и все переносы строк, и текст превратится в сплошную стену.
  -- Возвращаем текст с реальными \n между абзацами.
  local content = data.content
  content = content:gsub("\r\n", "\n"):gsub("\r", "\n")
  content = string_normalize(content)

  -- В конец залогиненного контента сайт подклеивает рекламную вставку с
  -- акцией ("...Recharge 100 and get 500 VIP coupons!...Immediate recharge..."),
  -- название праздника меняется (Dragon Boat Festival / Ching Ming и т.п.), но
  -- якорные строки "Recharge N and get N VIP coupons" и "Immediate recharge"
  -- стабильны. (?m) — ^/$ на каждой строке, поэтому вычищаем всю строку с
  -- якорем где бы тот ни стоял; вставка всегда в конце. Авторский текст с
  -- однокоренным "recharge" (без "VIP coupons") не затрагивается.
  content = regex_replace(content, "(?m)^.*Recharge \\d+ and get \\d+ VIP coupons.*\\n?", "")
  content = regex_replace(content, "(?m)^.*Immediate recharge.*\\n?", "")

  local paras = {}
  for line in content:gmatch("[^\n]+") do
    local t = string_trim(line)
    if t ~= "" then
      paras[#paras + 1] = t
    end
  end
  return table.concat(paras, "\n\n")
end
